'use strict';const M=Model,U=OmniUI,$=x=>document.getElementById(x);window.OMNI_PREVIEW=!window.omnibloomHost;let s=null,busy=false,mock={version:1,revision:0,enabled:true,exceptions:[]};function draw(){$('enabled').checked=!!s?.enabled;$('enabled').disabled=!s||busy;$('add').disabled=!s||busy;$('list').replaceChildren();for(const x of s?.exceptions||[]){const row=document.createElement('div');row.className='toolbar';const p=document.createElement('p');p.textContent=x.origin+' · '+(M.active(x,Date.now())?(x.duration==='session'?'This session':new Date(x.expiresAt).toLocaleString()):'Expired');const b=document.createElement('button');b.textContent='Remove exception';b.disabled=busy;b.onclick=()=>change('remove',{origin:x.origin});row.append(p,b);$('list').append(row)}}async function load(){if(busy)return;try{s=M.validate(await U.request('httpsPolicy.get',{},()=>mock));U.notify(window.OMNI_PREVIEW?'Preview · network policy is unchanged.':'HTTPS policy confirmed.')}catch(_){s=null;U.notify('HTTPS policy unavailable.')}draw()}async function change(type,params){if(busy||!s)return;busy=true;draw();try{if(type==='add')params=M.add(s,params.origin,params.duration,Date.now());else params={...params,expectedRevision:s.revision};const n=M.validate(await U.request('httpsPolicy.'+type,params,()=>{mock={...mock,revision:mock.revision+1};if(type==='set')mock.enabled=params.enabled;if(type==='add')mock.exceptions.push({origin:params.origin,duration:params.duration,expiresAt:params.duration==='day'?Date.now()+86400000:null});if(type==='remove')mock.exceptions=mock.exceptions.filter(x=>x.origin!==params.origin);return mock}));if(n.revision<=s.revision||type==='set'&&n.enabled!==params.enabled)throw Error('Policy not confirmed');s=n;if(type==='add')U.close();U.notify(window.OMNI_PREVIEW?'Preview updated.':'HTTPS settings updated.')}catch(e){$('error').textContent=e.message;U.notify('Change not confirmed.')}finally{busy=false;draw()}}$('enabled').onchange=()=>change('set',{enabled:$('enabled').checked});$('add').onclick=()=>{$('origin').value='';$('error').textContent='';U.modal('confirm')};$('allow').onclick=()=>change('add',{origin:$('origin').value,duration:$('duration').value});$('refresh').onclick=load;load();U.focus($('refresh'));
